/**
 * Unit tests for _getThreePanelHtmlContent() method in GitToolWindowProvider.
 *
 * Verifies the 2-panel flexbox layout HTML structure, CSS, and JS
 * generated by the method.
 */

import '../../setup';
import * as assert from 'assert';
import * as fs from 'fs';
import { GitToolWindowProvider } from '../../../src/ui-shell/GitToolWindowProvider';
import { ICommitDetails } from '../../../src/services/interfaces';
import { Uri, Webview } from '../../mocks/vscode';
import { bootWebviewEntry } from '../../helpers/bootWebviewEntry';

/** Inner HTML of the assembled document's `<body>` (island + panels + tags). */
function bodyOf(html: string): string {
  const match = /<body>([\s\S]*)<\/body>/.exec(html);
  return match ? match[1] : html;
}

/**
 * Helper to create minimal commit details.
 */
function makeCommitDetails(): ICommitDetails {
  return {
    hash: 'abc1234567890abcdef1234567890abcdef123456',
    message: 'Initial commit',
    author: { name: 'Test Author', email: 'test@example.com' },
    date: new Date('2024-01-15T10:30:00Z'),
    parents: [],
    branches: ['main'],
    tags: ['v1.0.0'],
    changedFiles: [
      { path: 'src/index.ts', status: 'added' },
      { path: 'README.md', status: 'modified' },
    ],
  };
}

/**
 * Create a mock Webview object for testing.
 */
function createMockWebview(): Webview {
  return {
    html: '',
    options: {},
    cspSource: 'https://mock.csp.source',
    onDidReceiveMessage: () => ({ dispose: () => {} }),
    postMessage: () => Promise.resolve(true),
    asWebviewUri: (uri: Uri) => uri,
  } as unknown as Webview;
}

describe('GitToolWindowProvider - _getThreePanelHtmlContent()', () => {
  let provider: GitToolWindowProvider;
  let mockWebview: Webview;

  beforeEach(() => {
    const extensionUri = Uri.file('/test/extension');
    provider = new GitToolWindowProvider(extensionUri);
    mockWebview = createMockWebview();
  });

  afterEach(() => {
    provider.dispose();
  });

  describe('Two panels arranged horizontally', () => {
    it('should contain exactly two panel containers as direct children of the layout', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(
        !html.includes('id="branch-panel"'),
        'Should NOT contain branch-panel (removed in 2-panel layout)'
      );
      assert.ok(html.includes('id="graph-panel"'), 'Should contain graph-panel');
      assert.ok(html.includes('id="details-panel"'), 'Should contain details-panel');
    });

    it('should arrange panels in left-to-right order: graph, details', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      const graphIndex = html.indexOf('id="graph-panel"');
      const detailsIndex = html.indexOf('id="details-panel"');

      assert.ok(graphIndex < detailsIndex, 'Graph panel should come before details panel');
    });

    it('should use a flexbox row layout container', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(
        html.includes('class="three-panel-layout"'),
        'Should have three-panel-layout class'
      );
      assert.ok(html.includes('flex-direction: row'), 'Should use flex-direction: row');
    });

    it('should include one draggable divider element between panels', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('data-divider="0"'), 'Should have divider (index 0)');

      const dividerMatches = html.match(/class="panel-divider"/g);
      assert.ok(dividerMatches, 'Should have panel-divider elements');
      assert.strictEqual(dividerMatches.length, 1, 'Should have exactly 1 divider');
    });

    it('should place divider between the correct panels', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      const graphStart = html.indexOf('id="graph-panel"');
      const divider0 = html.indexOf('data-divider="0"');
      const detailsStart = html.indexOf('id="details-panel"');

      assert.ok(divider0 > graphStart, 'Divider 0 should be after graph panel start');
      assert.ok(divider0 < detailsStart, 'Divider 0 should be before details panel');
    });

    it('should have role="application" on the layout container', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('role="application"'), 'Layout should have application role');
    });

    it('should have role="separator" on dividers', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('role="separator"'), 'Dividers should have separator role');
    });
  });

  describe('Default panel widths', () => {
    it('should use default widths [60%, 40%] when no widths specified', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('style="width: 60%;"'), 'Graph panel should be 60%');
      assert.ok(html.includes('style="width: 40%;"'), 'Details panel should be 40%');
    });

    it('should use custom widths when provided', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        [],
        undefined,
        [70, 30]
      );

      assert.ok(html.includes('style="width: 70%;"'), 'Graph panel should be 70%');
      assert.ok(html.includes('style="width: 30%;"'), 'Details panel should be 30%');
    });
  });

  describe('Vertical stacking at < 500px', () => {
    it('should include CSS for vertical stacking', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('vertical-layout'), 'Should include vertical-layout CSS class');
      assert.ok(
        html.includes('flex-direction: column'),
        'Should include column flex-direction for vertical stacking'
      );
    });

    it('applies the vertical-layout class from the bundled width check', () => {
      // The divider script (now folded into the entry) runs checkVerticalLayout
      // on boot: jsdom reports a 0-width layout (< 500px), so the class lands.
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );
      const h = bootWebviewEntry('git-core/gitToolWindow/webview/gitToolWindow', {
        bodyHtml: bodyOf(html),
      });
      try {
        const layout = h.document.querySelector('.three-panel-layout');
        assert.ok(layout?.classList.contains('vertical-layout'), 'width check toggled the class');
      } finally {
        h.dispose();
      }
    });
  });

  describe('Panel content rendering', () => {
    it('should render graph panel content', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('class="graph-panel"'), 'Should render graph panel');
      assert.ok(
        !html.includes('HEAD (Current Branch)'),
        'Should NOT render branch panel HEAD category'
      );
    });

    it('should render details placeholder when no commit details provided', () => {
      // The details panel is now filled client-side from the init island; boot
      // the entry over the assembled body and assert the placeholder renders.
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );
      const h = bootWebviewEntry('git-core/gitToolWindow/webview/gitToolWindow', {
        bodyHtml: bodyOf(html),
      });
      try {
        const details = h.document.getElementById('details-panel');
        assert.ok(
          details && details.textContent?.includes('Select a commit to view details'),
          'Should show placeholder when no commit selected'
        );
      } finally {
        h.dispose();
      }
    });

    it('should render commit details when provided', () => {
      const commitDetails = makeCommitDetails();
      // The details panel follows the SELECTION, so a commit whose details the
      // render carries is a selected commit — an empty selection renders the
      // placeholder no matter what details are passed.
      (
        provider as unknown as { _extendedLogState: { selectedCommits: Set<string> } }
      )._extendedLogState.selectedCommits = new Set([commitDetails.hash]);
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        [],
        commitDetails
      );

      assert.ok(html.includes('Initial commit'), 'Should render commit message');
      assert.ok(html.includes('Test Author'), 'Should render author name');
      assert.ok(
        html.includes('abc1234567890abcdef1234567890abcdef123456'),
        'Should render full hash'
      );
    });
  });

  describe('HTML document structure', () => {
    it('should produce a complete HTML document', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('<!DOCTYPE html>'), 'Should start with DOCTYPE');
      assert.ok(html.includes('<html lang="en">'), 'Should have html tag with lang');
      assert.ok(html.includes('<head>'), 'Should have head tag');
      assert.ok(html.includes('</head>'), 'Should close head tag');
      assert.ok(html.includes('<body>'), 'Should have body tag');
      assert.ok(html.includes('</body>'), 'Should close body tag');
      assert.ok(html.includes('</html>'), 'Should close html tag');
    });

    it('should include Content-Security-Policy meta tag', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('Content-Security-Policy'), 'Should include CSP meta tag');
      assert.ok(html.includes(mockWebview.cspSource), 'Should reference webview CSP source');
    });

    it('should include a nonce for script security', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('nonce-'), 'Should include nonce in CSP');
      const nonceMatch = html.match(/nonce="([^"]+)"/);
      assert.ok(nonceMatch, 'Should have nonce attribute on script tag');
    });

    it('should include inline styles', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('<style>'), 'Should have style tag');
      assert.ok(html.includes('</style>'), 'Should close style tag');
    });

    it('should include inline script', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('<script'), 'Should have script tag');
      assert.ok(html.includes('</script>'), 'Should close script tag');
    });
  });

  describe('Divider drag functionality (bundled entry)', () => {
    // Regression (F-C): the divider script used to reference a free `vscode`
    // from its own inline <script> IIFE, which was never defined there — so a
    // drag threw a ReferenceError and no panelResize ever persisted. Folded
    // into the entry it shares the real acquired handle; this drives the real
    // entry and asserts the drag now posts.
    it('posts panelResize on drag end (F-C: divider wired to the real vscode handle)', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );
      const h = bootWebviewEntry('git-core/gitToolWindow/webview/gitToolWindow', {
        bodyHtml: bodyOf(html),
      });
      try {
        const divider = h.document.querySelector('.panel-divider');
        assert.ok(divider, 'a panel divider is rendered');
        divider.dispatchEvent(
          new h.window.MouseEvent('mousedown', { bubbles: true, clientX: 200 })
        );
        h.document.dispatchEvent(
          new h.window.MouseEvent('mouseup', { bubbles: true, clientX: 260 })
        );
        assert.ok(
          h.posted.some((m) => (m as { type?: string }).type === 'panelResize'),
          'drag end must post panelResize'
        );
      } finally {
        h.dispose();
      }
    });

    // jsdom lays nothing out, so the min-width clamp + keyboard-nudge paths
    // (which gate on getBoundingClientRect) can't be exercised here; assert the
    // bundled entry source carries them so the behavior can't silently vanish.
    it('the entry carries the divider min-width clamp + keyboard nudge', () => {
      const entrySrc = fs.readFileSync(
        require.resolve('../../../src/git-core/gitToolWindow/webview/gitToolWindow.ts'),
        'utf8'
      );
      assert.ok(entrySrc.includes('MIN_PANEL_PX'), 'min-width constant present');
      assert.ok(entrySrc.includes('100'), '100px minimum present');
      assert.ok(entrySrc.includes('ArrowLeft') && entrySrc.includes('ArrowRight'), 'arrow keys');
    });
  });

  describe('CSS styling', () => {
    it('should include panel divider cursor style', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('cursor: col-resize'), 'Divider should have col-resize cursor');
    });

    it('should include resizing body class styles', () => {
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        []
      );

      assert.ok(html.includes('body.resizing'), 'Should include resizing body class');
      assert.ok(html.includes('user-select: none'), 'Should disable text selection during resize');
    });
  });
});
